('127.170.d.8.E',3,'Radio stations in the United States follow broadcast rules set by the:','["Department of Agriculture", "National Park Service", "Federal Communications Commission", "Postal Inspection Service"]'::jsonb,2,'Regulations.','original'),
('127.170.d.8.E',4,'Broadcasting indecent content at times prohibited by regulators can lead to:','["Free equipment", "Bonus awards", "Wider licenses", "Fines for the station"]'::jsonb,3,'Compliance.','original'),
