('127.170.d.15.E',4,'Writing automation for a filter sweep on a synth is done to:','["Reduce file size", "Stop the track", "Delete the plug-in", "Change the sound smoothly over time"]'::jsonb,3,'Automation.','original'),
('127.170.d.15.F',3,'Audio prepared for a smartphone app is often delivered as a:','["Compressed file such as AAC or MP3", "Paper score", "Radio tower", "Vinyl record"]'::jsonb,0,'Delivery formats.','original'),
('127.170.d.15.F',4,'For CD mastering, the standard audio format delivered is:','["32-bit, 192 kHz only", "16-bit, 44.1 kHz", "24-bit, 11 kHz", "8-bit, 8 kHz"]'::jsonb,1,'Delivery formats.','original'),
('127.171.d.4',3,'Not sharing your password or personal details with strangers in an online game is practicing:','["Level design", "Game balance", "Cyber safety", "Frame rate"]'::jsonb,2,'Cyber safety procedures.','original'),
('127.171.d.4',4,'A message in a game chat offers free in-game items if you click an unknown link. The safe response is to:','["Send it to friends", "Enter your password", "Click it quickly", "Ignore it and report the message"]'::jsonb,3,'Cyber safety.','original'),
('127.171.d.7',3,'A designer who learns keyboard shortcuts in a game engine is applying technical skills for:','["Efficiency", "Slowdown", "Confusion", "Distraction"]'::jsonb,0,'Technical skills.','original'),
('127.171.d.7',4,'Reusing a prefab (a saved object template) across levels helps a developer:','["Add errors", "Save time and keep objects consistent", "Lose files", "Slow loading"]'::jsonb,1,'Efficiency.','original'),
('127.171.d.12',3,'A student plays a classmate''s game and notes what is fun and what is confusing. This is:','["Guessing", "Hiding bugs", "Evaluating a product with critical thinking", "Copying"]'::jsonb,2,'Evaluate a product.','original'),
('127.171.d.12',4,'The best evidence for judging whether a puzzle level is too hard is:','["A random guess", "The designer''s mood", "The file size", "How many testers complete it and where they get stuck"]'::jsonb,3,'Evaluate.','original'),
('127.171.d.14',3,'A student plans, builds, tests, and shares a simple platformer. This is a:','["Video game design project", "Lunch menu", "Reading assignment", "Hall pass"]'::jsonb,0,'Create video game projects.','original'),
('127.171.d.14',4,'Before building a game, a design team often writes a short document describing goals, rules, and characters called a:','["Receipt", "Game design document", "Menu", "Pay stub"]'::jsonb,1,'Design projects.','original'),
('127.171.d.16',3,'A game character falls through the floor. The developer first tries to:','["Ignore it", "Blame the player", "Test to find what causes the bug", "Delete the game"]'::jsonb,2,'Problem-solving strategies.','original'),
('127.171.d.16',4,'Debugging by changing one thing at a time is useful because it:','["Hides the bug", "Wastes time", "Adds more bugs", "Shows which change fixed or caused the problem"]'::jsonb,3,'Problem solving.','original'),
('127.171.d.17',3,'Coding a game with names like playerSpeed instead of x1 makes code:','["Easier to read and fix", "Harder to read", "Unusable", "Slower to run always"]'::jsonb,0,'Expressive coding.','original'),
('127.171.d.17',4,'Putting repeated code into a function lets a developer:','["Avoid testing", "Reuse it instead of retyping it", "Delete the game", "Type it again each time"]'::jsonb,1,'Efficient coding.','original'),
('127.171.d.18',3,'A tester says, "The jump feels floaty, but the art looks great." This is:','["Spam", "A bug", "Constructive criticism", "An insult"]'::jsonb,2,'Constructive criticism.','original'),
('127.171.d.18',4,'A designer responds well to feedback on a prototype by:','["Ignoring it", "Quitting", "Arguing", "Thanking the tester and trying useful suggestions"]'::jsonb,3,'Apply criticism.','original'),
('127.171.d.1.A',3,'Writing clear instructions for how to play a game demonstrates:','["English language arts skills", "Welding skills", "Plumbing skills", "Gardening skills"]'::jsonb,0,'ELA.','original'),
('127.171.d.1.A',4,'A game''s story dialogue is easier to follow when the writer uses correct:','["Random letters", "Spelling, punctuation, and grammar", "No spaces", "All capitals only"]'::jsonb,1,'ELA.','original'),
('127.171.d.1.B',3,'A character has 120 health points and takes 15 points of damage per hit. How many hits does it take to reach zero?','["6", "12", "8", "10"]'::jsonb,2,'120 / 15 = 8.','original'),
('127.171.d.1.B',4,'A game gives 250 points per level and a 10% bonus for finishing fast. What are the points for a fast finish?','["300", "260", "225", "275"]'::jsonb,3,'250 + 25 = 275.','original'),
('127.171.d.2.A',3,'Explaining game rules to a young player in simple words is adapting language to the:','["Audience", "Console", "Platform", "Screen size"]'::jsonb,0,'Adapt language.','original'),
('127.171.d.2.A',4,'A pitch to investors uses more business terms than a tutorial for players because of the:','["Frame rate", "Purpose and audience", "Controller size", "File type"]'::jsonb,1,'Adapt language.','original'),
('127.171.d.2.B',3,'Writing a clear outline of levels, characters, and items before building is:','["Rendering", "Debugging", "Organizing information", "Compiling"]'::jsonb,2,'Organize information.','original'),
('127.171.d.2.B',4,'A designer lists tasks in order from planning to testing so the team knows:','["Who is the loudest", "Which game is best", "Nothing", "What to do and when"]'::jsonb,3,'Organize.','original'),
('127.171.d.2.C',3,'A designer reports that 70% of testers quit at level three. This is:','["Interpreting and communicating information", "Decorating", "Hiding data", "Guessing"]'::jsonb,0,'Interpret information.','original'),
('127.171.d.2.C',4,'Showing a team a chart of where players fail in a level helps them:','["Delete levels", "Decide where to adjust difficulty", "Add random bugs", "Ignore problems"]'::jsonb,1,'Communicate.','original'),
('127.171.d.2.D',3,'A teammate looks at the speaker, avoids interruptions, and asks follow-up questions. This is:','["Ignoring", "Daydreaming", "Active listening", "Multitasking"]'::jsonb,2,'Active listening.','original'),
('127.171.d.2.D',4,'Restating a teammate''s bug report before fixing it ensures:','["The game is faster", "The report is wrong", "The bug disappears", "You understood the problem"]'::jsonb,3,'Active listening.','original'),
('127.171.d.2.E',3,'Working with teammates who have different backgrounds and ideas requires:','["Respectful communication", "Teasing", "Talking over others", "Ignoring ideas"]'::jsonb,0,'Diverse individuals.','original'),
('127.171.d.2.E',4,'A game with characters and stories from many cultures is more likely to:','["Lose players", "Appeal to a wider audience", "Confuse everyone", "Reduce creativity"]'::jsonb,1,'Diversity.','original'),
('127.171.d.3.A',3,'A team decides which of two enemy designs is more fun by testing both with players. This is:','["Random choice", "Guessing", "Critical thinking in a group", "Copying"]'::jsonb,2,'Critical thinking.','original'),
('127.171.d.3.A',4,'Choosing a game engine after comparing cost, features, and platform support relies on:','["The loudest voice", "Habit only", "A coin flip", "Evidence-based critical thinking"]'::jsonb,3,'Critical thinking.','original'),
('127.171.d.3.B',3,'Two teammates disagree about a level layout. A good interpersonal approach is to:','["Listen to both and build a test version of each", "Insist on one", "Stay silent", "Walk away"]'::jsonb,0,'Interpersonal skills.','original'),
('127.171.d.3.B',4,'Splitting work fairly by strengths on a game team shows:','["Avoidance", "Group problem solving", "Competition", "Poor planning"]'::jsonb,1,'Interpersonal skills.','original'),
('127.171.d.5.A',3,'A team member who organizes a testing day and guides others shows:','["Delay", "Distraction", "Leadership", "Avoidance"]'::jsonb,2,'Leadership.','original'),
('127.171.d.5.B',3,'Offering ideas and listening during a brainstorming session is:','["Skipping class", "Working alone", "Ignoring teammates", "Participating in a group setting"]'::jsonb,3,'Group participation.','original'),
('127.171.d.5.A',4,'A game team lead keeps the team on schedule by:','["Setting clear milestones and checking progress", "Never meeting", "Ignoring deadlines", "Doing every job alone"]'::jsonb,0,'Leadership.','original'),
('127.171.d.5.B',4,'A good participant in a game jam team:','["Works in secret", "Shares tasks and communicates problems early", "Blames others", "Hides problems"]'::jsonb,1,'Group participation.','original'),
('127.171.d.6.A',3,'Giving credit to the artist who made the character in your game is:','["Optional", "A bug", "Ethical conduct", "Wasteful"]'::jsonb,2,'Ethical conduct.','original'),
('127.171.d.6.A',4,'Keeping a friend''s unreleased prototype private until they publish it is:','["Poor teamwork", "Breaking rules", "A mistake", "Respecting others'' rights and privacy"]'::jsonb,3,'Ethical conduct.','original'),
('127.171.d.6.B',3,'Copyright law applies to a game''s code, art, and music because these are:','["Original creative works", "Public domain by default", "Not owned by anyone", "Free to copy"]'::jsonb,0,'Copyright.','original'),
('127.171.d.6.B',4,'Using a popular song in your game released online without permission can:','["Be required", "Violate copyright law", "Be legal", "Improve the song"]'::jsonb,1,'Copyright.','original'),
('127.171.d.6.C',3,'Using assets that carry a free license and following the license terms shows:','["Carelessness", "Plagiarism", "Respect for intellectual property", "Piracy"]'::jsonb,2,'IP respect.','original'),
('127.171.d.6.C',4,'Making a game with your own original characters instead of copying a famous brand''s is a way to:','["Reduce quality", "Lose originality", "Break the law", "Avoid infringing on someone else''s work"]'::jsonb,3,'IP respect.','original'),
('127.171.d.6.D',3,'A school''s acceptable use policy says students should use computers for:','["Approved learning tasks", "Anything online", "Hacking", "Downloading games"]'::jsonb,0,'Acceptable use policies.','original'),
('127.171.d.6.D',4,'Good online etiquette in a team chat includes:','["Insulting others", "Writing respectfully", "Using all caps to yell", "Spamming"]'::jsonb,1,'Etiquette.','original'),
('127.171.d.6.E',3,'Video games influence society by affecting:','["Only trees", "Only weather", "Entertainment, education, and culture", "Only roads"]'::jsonb,2,'Industry impact.','original'),
('127.171.d.6.E',4,'Educational games can help society by:','["Replacing all schools", "Hiding facts", "Reducing learning", "Teaching skills in engaging ways"]'::jsonb,3,'Industry impact.','original'),
('127.171.d.8.A',3,'Knowing how to save, organize, and open files on Windows or macOS is knowledge of:','["Computer operating systems", "Cooking", "Sports rules", "Weather maps"]'::jsonb,0,'Operating systems.','original'),
('127.171.d.8.A',4,'A game built for one operating system may need changes to run on another because of:','["Different seating", "Differences in system requirements", "Different weather", "Different clocks"]'::jsonb,1,'Operating systems.','original'),
('127.171.d.8.B',3,'A graphics card (GPU) in a gaming computer mainly helps with:','["Printing", "Charging", "Rendering images", "Cooling the room"]'::jsonb,2,'Hardware.','original'),
('127.171.d.8.B',4,'Adding more RAM can help a game development computer by:','["Printing faster", "Increasing the volume", "Lowering the screen size", "Running more programs at once"]'::jsonb,3,'Hardware components.','original'),
('127.171.d.8.C',3,'Trimming a sound effect and normalizing its volume before adding it to a game is:','["Sound editing", "Level scripting", "Texture painting", "3D modeling"]'::jsonb,0,'Sound editing.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_29_v1'
